from fractions import Fraction
from math import comb

def risk_neutral_q(u, d, r):
    """q = (1 + r - d) / (u - d), exactly. Raise ValueError unless 0 < q < 1."""
    u, d, r = Fraction(u), Fraction(d), Fraction(r)
    q = (1 + r - d) / (u - d)
    if not 0 < q < 1:
        raise ValueError("no risk-neutral probability: arbitrage")
    return q

def tree_price(payoff, S0, u, d, r, n):
    """Price of payoff(S_n) on an n-step recombining tree: E_Q[payoff]/(1 + r)^n, exact."""
    S0, u, d, r = Fraction(S0), Fraction(u), Fraction(d), Fraction(r)
    q = risk_neutral_q(u, d, r)
    total = Fraction(0)
    for k in range(n + 1):
        total += comb(n, k) * q ** k * (1 - q) ** (n - k) * payoff(S0 * u ** k * d ** (n - k))
    return total / (1 + r) ** n

def is_discounted_martingale(S0, u, d, r, p, n):
    """True when, at every node before step n, p * (up price) + (1 - p) * (down price)
    equals the node's price, with prices discounted to time 0."""
    S0, u, d, r, p = Fraction(S0), Fraction(u), Fraction(d), Fraction(r), Fraction(p)
    def price(t, k):
        return S0 * u ** k * d ** (t - k) / (1 + r) ** t
    for t in range(n):
        for k in range(t + 1):
            if p * price(t + 1, k + 1) + (1 - p) * price(t + 1, k) != price(t, k):
                return False
    return True
